<?php use App\Core\Csrf; $invoice=$invoice??[]; $channels=$channels??[]; $token=$token??''; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pay School Fees | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fb;color:#172033}.wrap{max-width:720px;margin:30px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:22px;margin-bottom:16px}label{display:block;margin:13px 0}input,select{width:100%;box-sizing:border-box;padding:11px;border:1px solid #ccd1db;border-radius:8px;margin-top:5px}button{padding:12px 18px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:600;width:100%}.amount{font-size:30px;font-weight:700}.muted{color:#667085}.method{border:1px solid #e5e7eb;border-radius:10px;padding:12px;margin:8px 0}</style></head><body><main class="wrap"><section class="card"><h1>Pay School Fees</h1><p><?= htmlspecialchars(($invoice['first_name']??'').' '.($invoice['last_name']??'')) ?></p><p class="muted">Invoice <?= htmlspecialchars((string)($invoice['invoice_no']??'')) ?></p><p class="amount">KES <?= number_format((float)($invoice['balance']??0),2) ?></p><p class="muted">Outstanding balance</p></section><section class="card"><form method="post" action="/pay/<?= htmlspecialchars($token,ENT_QUOTES) ?>"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES) ?>"><label>Amount (KES)<input type="number" name="amount" min="1" max="<?= htmlspecialchars((string)$invoice['balance']) ?>" step="0.01" value="<?= htmlspecialchars((string)$invoice['balance']) ?>" required></label><label>Payment method<select name="channel_id" required><option value="">Select payment method</option><?php foreach($channels as $channel): ?><option value="<?= (int)$channel['id'] ?>"><?= htmlspecialchars($channel['name']) ?><?php if($channel['provider']): ?> — <?= htmlspecialchars((string)$channel['provider']) ?><?php endif; ?></option><?php endforeach; ?></select></label><label>Email <span class="muted">(required for Paystack)</span><input type="email" name="email" autocomplete="email"></label><label>Phone <span class="muted">(required for M-Pesa)</span><input type="tel" name="phone" autocomplete="tel" placeholder="07XXXXXXXX"></label><button>Continue to payment</button></form></section><p class="muted">Your school controls which payment methods are available. Payment is confirmed only after the provider verifies the transaction.</p></main></body></html>
